    'RegistrationText'=>'Rekisteröityille SimpleRisk-esiintymille myönnetään välittömästi pääsy Upgrade and Secure Controls Framework (SCF) Extraihin. Upgrade Extra tarjoaa mahdollisuuden varmuuskopioida ja päivittää SimpleRisk-esiintymäsi napin painalluksella. Secure Controls Framework (SCF) Extra tarjoaa yhteisen ohjauskehyksen, joka on integroitu SimpleRisk Governance -toimintoon. Kun rekisteröidyt SimpleRiskin, rekisteröintitietosi lähetetään SimpleRiskin isännöimälle palvelimelle. SimpleRisk käyttää annettuja rekisteröintitietoja ilmoittaakseen asiakkaille uusista julkaisuista ja tietoturvapäivityksistä. Rekisteröimällä SimpleRisk voit osallistua markkinointiviestintään, mutta voit kieltäytyä siitä milloin tahansa käyttämällä näissä viestinnöissä olevaa tilauksen peruutuslinkkiä. SimpleRisk kunnioittaa asiakkaidemme yksityisyyttä, eikä SimpleRisk-rekisteröintiprosessin kautta meille annettuja tietoja koskaan myydä kolmannelle osapuolelle.',
