    'SoaImplemented' => 'Toteutettu',
    'SoaImplementedPartial' => 'Osittainen',

    // The cover block.
    'SoaGeneratedOn' => 'Luotu',
    'SoaExcludedCount' => 'Poissuljettu',

    // The prompt shown when the framework has never been given the two cover
